package com.delivery.platform.delivery.application;import com.delivery.platform.common.*;import com.delivery.platform.delivery.domain.DeliveryTypes.*;import com.delivery.platform.identity.security.IdentityPrincipal;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service public class DeliveryService{private final JdbcClient db;private final DeliveryCoverageService coverage;private final CourierAssignmentStrategy assignment;public DeliveryService(JdbcClient db,DeliveryCoverageService coverage,CourierAssignmentStrategy assignment){this.db=db;this.coverage=coverage;this.assignment=assignment;}public record Delivery(UUID id,UUID orderId,UUID merchantId,UUID branchId,UUID customerId,UUID courierId,UUID deliveryAddressId,Status status,Type deliveryType,BigDecimal distanceKm,Integer estimatedDurationMinutes,BigDecimal deliveryFee,String currency,String pickupNotes,String deliveryNotes,String failureReason,long version,Instant createdAt){}public record History(UUID id,Status status,String oldStatus,String actorType,String notes,Instant createdAt){}public record Courier(UUID id,UUID userId,String name,String status,String vehicleType,String phone,int maxActiveDeliveries,int currentActiveDeliveries,String availability,UUID zoneId,Instant updatedAt){}public record CourierCandidate(UUID id,String firstName,String lastName,String email,String phone){}public record Zone(UUID id,UUID merchantId,UUID branchId,String name,String description,String zoneType,String areas,boolean active,BigDecimal minimumOrderAmount,BigDecimal baseDeliveryFee,String currency,int estimatedMinutes){}
 public DeliveryCoverageService.Quote quote(IdentityPrincipal p,UUID merchant,UUID branch,UUID address,BigDecimal subtotal){return coverage.quote(p.tenantId(),p.userId(),merchant,branch,address,subtotal);} DeliveryCoverageService.Quote deliveryQuote(Type type,UUID tenant,UUID customer,UUID merchant,UUID branch,UUID address,BigDecimal subtotal,String currency){if(type==Type.PICKUP)return new DeliveryCoverageService.Quote(true,null,BigDecimal.ZERO,0,BigDecimal.ZERO,currency,BigDecimal.ZERO,null,"Recojo en tienda");return coverage.quote(tenant,customer,merchant,branch,address,subtotal);}
 @Transactional public Delivery create(IdentityPrincipal p,UUID orderId,Type type,String pickup,String notes,String key){required(key);Optional<UUID> old=db.sql("select id from deliveries where tenant_id=:t and order_id=:o and status not in('DELIVERED','FAILED','CANCELLED','REJECTED','EXPIRED')").param("t",p.tenantId()).param("o",orderId).query(UUID.class).optional();if(old.isPresent())return one(p,old.get());var o=db.sql("select merchant_id,branch_id,customer_id,delivery_address_id,subtotal,payment_status,status,currency from orders where id=:o and tenant_id=:t and (customer_id=:u or :admin)").param("o",orderId).param("t",p.tenantId()).param("u",p.userId()).param("admin",p.permissions().contains("DELIVERY_ADMIN")).query((r,n)->new Object[]{r.getObject("merchant_id",UUID.class),r.getObject("branch_id",UUID.class),r.getObject("customer_id",UUID.class),r.getObject("delivery_address_id",UUID.class),r.getBigDecimal("subtotal"),r.getString("payment_status"),r.getString("status"),r.getString("currency")}).optional().orElseThrow(()->err(HttpStatus.NOT_FOUND,"ORDER_NOT_FOUND","Pedido no encontrado"));if(Set.of("CANCELLED","REJECTED","DELIVERED").contains(o[6]))throw err(HttpStatus.CONFLICT,"DELIVERY_INVALID_STATE","El pedido no admite entrega");boolean cod=db.sql("select count(*) from payments where order_id=:o and tenant_id=:t and payment_method='CASH_ON_DELIVERY' and status='PENDING'").param("o",orderId).param("t",p.tenantId()).query(Integer.class).single()>0;if(!"PAID".equals(o[5])&&!cod)throw err(HttpStatus.CONFLICT,"PAYMENT_INVALID_STATE","El pedido requiere pago confirmado");var q=deliveryQuote(type,p.tenantId(),(UUID)o[2],(UUID)o[0],(UUID)o[1],(UUID)o[3],(BigDecimal)o[4],(String)o[7]);if(!q.eligible())throw err(HttpStatus.CONFLICT,q.reasonCode(),q.message());UUID id=UUID.randomUUID();String snapshot=db.sql("select jsonb_build_object('addressLine',address_line,'district',district,'recipientName',recipient_name,'phone',phone)::text from delivery_addresses where id=:a and tenant_id=:t").param("a",o[3]).param("t",p.tenantId()).query(String.class).single();db.sql("insert into deliveries(id,tenant_id,order_id,merchant_id,branch_id,customer_id,delivery_address_id,address_snapshot,status,delivery_type,distance_km,estimated_duration_minutes,delivery_fee,currency,pickup_notes,delivery_notes) values(:i,:t,:o,:m,:b,:c,:a,cast(:s as jsonb),'PENDING',:y,:d,:e,:f,:u,:p,:n)").param("i",id).param("t",p.tenantId()).param("o",orderId).param("m",o[0]).param("b",o[1]).param("c",o[2]).param("a",o[3]).param("s",snapshot).param("y",type.name()).param("d",q.distanceKm()).param("e",q.estimatedMinutes()).param("f",q.deliveryFee()).param("u",q.currency()).param("p",pickup).param("n",notes).update();history(p,id,null,Status.PENDING,"DELIVERY_CREATED");audit(p,"DELIVERY_CREATED",id);return one(p,id);}
 @Transactional public Delivery assign(IdentityPrincipal p,UUID id,UUID courier,String kind,String key){required(key);Delivery d=one(p,id);if(d.courierId()!=null)return d;if(courier==null)courier=assignment.select(p.tenantId(),d.branchId(),null).orElseThrow(()->err(HttpStatus.CONFLICT,"COURIER_NOT_AVAILABLE","No hay repartidores disponibles"));int ok=db.sql("select count(*) from courier_profiles c join courier_availability a on a.courier_id=c.id where c.id=:c and c.tenant_id=:t and c.status='ACTIVE' and a.status='ONLINE' and c.current_active_deliveries<c.max_active_deliveries").param("c",courier).param("t",p.tenantId()).query(Integer.class).single();if(ok==0)throw err(HttpStatus.CONFLICT,"COURIER_NOT_AVAILABLE","Repartidor no disponible");try{db.sql("insert into delivery_assignments(id,tenant_id,delivery_id,courier_id,status,assignment_type,assigned_by,idempotency_key,expires_at) values(gen_random_uuid(),:t,:d,:c,'PENDING',:y,:u,:k,now()+interval '5 minutes')").param("t",p.tenantId()).param("d",id).param("c",courier).param("y",kind).param("u",p.userId()).param("k",key).update();}catch(Exception e){return one(p,id);}db.sql("update deliveries set courier_id=:c,status='ASSIGNED',assigned_at=now(),version=version+1,updated_at=now() where id=:d and tenant_id=:t and version=:v").param("c",courier).param("d",id).param("t",p.tenantId()).param("v",d.version()).update();db.sql("update courier_profiles set current_active_deliveries=current_active_deliveries+1 where id=:c").param("c",courier).update();history(p,id,d.status(),Status.ASSIGNED,"COURIER_ASSIGNED");syncOrder(p,d.orderId(),Status.ASSIGNED);audit(p,"COURIER_ASSIGNED",id);return one(p,id);}
 @Transactional public Delivery status(IdentityPrincipal p,UUID id,Status next,String notes){Delivery d=one(p,id);com.delivery.platform.delivery.domain.DeliveryTypes.validate(d.status(),next);if(next==Status.DELIVERED&&d.courierId()==null&&d.deliveryType()!=Type.PICKUP)throw err(HttpStatus.CONFLICT,"COURIER_NOT_AVAILABLE","La entrega requiere repartidor");int n=db.sql("update deliveries set status=:s,failure_reason=case when :s='FAILED' then :n else failure_reason end,accepted_at=case when :s='ACCEPTED' then now() else accepted_at end,picked_up_at=case when :s='PICKED_UP' then now() else picked_up_at end,delivered_at=case when :s='DELIVERED' then now() else delivered_at end,cancelled_at=case when :s='CANCELLED' then now() else cancelled_at end,version=version+1,updated_at=now() where id=:d and tenant_id=:t and version=:v").param("s",next.name()).param("n",notes).param("d",id).param("t",p.tenantId()).param("v",d.version()).update();if(n==0)throw err(HttpStatus.CONFLICT,"DELIVERY_CONCURRENT_UPDATE","La entrega fue actualizada por otro usuario");history(p,id,d.status(),next,notes);syncOrder(p,d.orderId(),next);if(next==Status.DELIVERED){db.sql("update payments set status='PAID',captured_amount=amount,captured_at=now(),updated_at=now() where order_id=:o and tenant_id=:t and payment_method='CASH_ON_DELIVERY' and status='PENDING'").param("o",d.orderId()).param("t",p.tenantId()).update();if(d.courierId()!=null)db.sql("update courier_profiles set current_active_deliveries=greatest(0,current_active_deliveries-1) where id=:c").param("c",d.courierId()).update();audit(p,"DELIVERY_COMPLETED",id);}else audit(p,"DELIVERY_STATUS_UPDATED",id);return one(p,id);}
 public Delivery one(IdentityPrincipal p,UUID id){return db.sql("select * from deliveries where id=:i and tenant_id=:t and (customer_id=:u or :admin)").param("i",id).param("t",p.tenantId()).param("u",p.userId()).param("admin",p.permissions().contains("DELIVERY_ADMIN")).query((r,n)->map(r)).optional().orElseThrow(()->err(HttpStatus.NOT_FOUND,"DELIVERY_NOT_FOUND","Entrega no encontrada"));}public PageResponse<Delivery> list(IdentityPrincipal p,String status,int page,int size){int z=Math.min(Math.max(size,1),100),pg=Math.max(page,0);String w=" from deliveries where tenant_id=:t and (cast(:s as varchar) is null or status=:s)";var rows=db.sql("select *"+w+" order by created_at desc limit :z offset :o").param("t",p.tenantId()).param("s",status).param("z",z).param("o",pg*z).query((r,n)->map(r)).list();long c=db.sql("select count(*)"+w).param("t",p.tenantId()).param("s",status).query(Long.class).single();return PageResponse.of(rows,pg,z,c);}public List<History> history(IdentityPrincipal p,UUID id){one(p,id);return db.sql("select * from delivery_status_history where tenant_id=:t and delivery_id=:d order by created_at").param("t",p.tenantId()).param("d",id).query((r,n)->new History(r.getObject("id",UUID.class),Status.valueOf(r.getString("status")),r.getString("old_status"),r.getString("actor_type"),r.getString("notes"),r.getTimestamp("created_at").toInstant())).list();}
 public List<Courier> couriers(IdentityPrincipal p,boolean available){String extra=available?" and a.status='ONLINE' and c.status='ACTIVE' and c.current_active_deliveries<c.max_active_deliveries":"";return db.sql("select c.*,u.first_name||' '||u.last_name name,a.status availability,a.zone_id,a.updated_at availability_updated from courier_profiles c join users u on u.id=c.user_id left join courier_availability a on a.courier_id=c.id where c.tenant_id=:t"+extra+" order by name").param("t",p.tenantId()).query((r,n)->new Courier(r.getObject("id",UUID.class),r.getObject("user_id",UUID.class),r.getString("name"),r.getString("status"),r.getString("vehicle_type"),r.getString("phone"),r.getInt("max_active_deliveries"),r.getInt("current_active_deliveries"),r.getString("availability"),r.getObject("zone_id",UUID.class),r.getTimestamp("availability_updated")==null?null:r.getTimestamp("availability_updated").toInstant())).list();}
 public List<CourierCandidate> courierCandidates(IdentityPrincipal p){return db.sql("select u.id,u.first_name,u.last_name,u.email,u.phone from users u where u.tenant_id=:t and u.status='ACTIVE' and not exists(select 1 from courier_profiles c where c.tenant_id=:t and c.user_id=u.id) order by u.first_name,u.last_name,u.email").param("t",p.tenantId()).query((r,n)->new CourierCandidate(r.getObject("id",UUID.class),r.getString("first_name"),r.getString("last_name"),r.getString("email"),r.getString("phone"))).list();}@Transactional public Courier createCourier(IdentityPrincipal p,UUID user,String vehicle,String phone,int max){int valid=db.sql("select count(*) from users where id=:u and tenant_id=:t and status='ACTIVE'").param("u",user).param("t",p.tenantId()).query(Integer.class).single();if(valid==0)throw err(HttpStatus.BAD_REQUEST,"INVALID_COURIER_USER","Selecciona un usuario activo de tu empresa");int exists=db.sql("select count(*) from courier_profiles where user_id=:u and tenant_id=:t").param("u",user).param("t",p.tenantId()).query(Integer.class).single();if(exists>0)throw err(HttpStatus.CONFLICT,"COURIER_ALREADY_EXISTS","El usuario ya tiene un perfil de repartidor");UUID id=UUID.randomUUID();db.sql("insert into courier_profiles(id,tenant_id,user_id,vehicle_type,phone,max_active_deliveries) values(:i,:t,:u,:v,:p,:m)").param("i",id).param("t",p.tenantId()).param("u",user).param("v",vehicle).param("p",phone).param("m",max).update();db.sql("insert into courier_availability(id,tenant_id,courier_id,status) values(gen_random_uuid(),:t,:c,'OFFLINE')").param("t",p.tenantId()).param("c",id).update();return couriers(p,false).stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();}@Transactional public void availability(IdentityPrincipal p,UUID id,String status,UUID zone,UUID branch){int n=db.sql("update courier_availability set status=:s,zone_id=:z,branch_id=:b,updated_at=now() where courier_id=:c and tenant_id=:t").param("s",status).param("z",zone).param("b",branch).param("c",id).param("t",p.tenantId()).update();if(n==0)throw err(HttpStatus.NOT_FOUND,"COURIER_NOT_FOUND","Repartidor no encontrado");}
 public List<Zone> zones(IdentityPrincipal p){return db.sql("select * from delivery_zones where tenant_id=:t order by name").param("t",p.tenantId()).query((r,n)->mapZone(r)).list();}@Transactional public Zone saveZone(IdentityPrincipal p,UUID id,UUID merchant,UUID branch,String name,String description,String type,String areas,boolean active,BigDecimal min,BigDecimal fee,String currency,int minutes){int merchantOwned=db.sql("select count(*) from merchants where id=:m and tenant_id=:t").param("m",merchant).param("t",p.tenantId()).query(Integer.class).single();if(merchantOwned==0)throw err(HttpStatus.BAD_REQUEST,"INVALID_ZONE_MERCHANT","Selecciona un comercio vÃ¡lido");if(branch!=null){int branchOwned=db.sql("select count(*) from branches where id=:b and merchant_id=:m and tenant_id=:t").param("b",branch).param("m",merchant).param("t",p.tenantId()).query(Integer.class).single();if(branchOwned==0)throw err(HttpStatus.BAD_REQUEST,"INVALID_ZONE_BRANCH","La sucursal debe pertenecer al comercio seleccionado");}UUID zone=id==null?UUID.randomUUID():id;if(id==null)db.sql("insert into delivery_zones(id,tenant_id,merchant_id,branch_id,name,description,zone_type,areas,active,minimum_order_amount,base_delivery_fee,currency,estimated_minutes) values(:i,:t,:m,:b,:n,:d,:y,:a,:x,:o,:f,:c,:e)").param("i",zone).param("t",p.tenantId()).param("m",merchant).param("b",branch).param("n",name).param("d",description).param("y",type).param("a",areas).param("x",active).param("o",min).param("f",fee).param("c",currency).param("e",minutes).update();else db.sql("update delivery_zones set name=:n,description=:d,zone_type=:y,areas=:a,active=:x,minimum_order_amount=:o,base_delivery_fee=:f,currency=:c,estimated_minutes=:e,updated_at=now() where id=:i and tenant_id=:t").param("n",name).param("d",description).param("y",type).param("a",areas).param("x",active).param("o",min).param("f",fee).param("c",currency).param("e",minutes).param("i",zone).param("t",p.tenantId()).update();return zones(p).stream().filter(x->x.id().equals(zone)).findFirst().orElseThrow();}@Transactional public void deleteZone(IdentityPrincipal p,UUID id){db.sql("update delivery_zones set active=false,updated_at=now() where id=:i and tenant_id=:t").param("i",id).param("t",p.tenantId()).update();}
 private Delivery map(java.sql.ResultSet r)throws java.sql.SQLException{return new Delivery(r.getObject("id",UUID.class),r.getObject("order_id",UUID.class),r.getObject("merchant_id",UUID.class),r.getObject("branch_id",UUID.class),r.getObject("customer_id",UUID.class),r.getObject("courier_id",UUID.class),r.getObject("delivery_address_id",UUID.class),Status.valueOf(r.getString("status")),Type.valueOf(r.getString("delivery_type")),r.getBigDecimal("distance_km"),(Integer)r.getObject("estimated_duration_minutes"),r.getBigDecimal("delivery_fee"),r.getString("currency"),r.getString("pickup_notes"),r.getString("delivery_notes"),r.getString("failure_reason"),r.getLong("version"),r.getTimestamp("created_at").toInstant());}private Zone mapZone(java.sql.ResultSet r)throws java.sql.SQLException{return new Zone(r.getObject("id",UUID.class),r.getObject("merchant_id",UUID.class),r.getObject("branch_id",UUID.class),r.getString("name"),r.getString("description"),r.getString("zone_type"),r.getString("areas"),r.getBoolean("active"),r.getBigDecimal("minimum_order_amount"),r.getBigDecimal("base_delivery_fee"),r.getString("currency"),r.getInt("estimated_minutes"));}private void history(IdentityPrincipal p,UUID id,Status old,Status next,String notes){db.sql("insert into delivery_status_history(id,tenant_id,delivery_id,status,actor_id,actor_type,notes,old_status,correlation_id) values(gen_random_uuid(),:t,:d,:s,:u,'USER',:n,:o,:c)").param("t",p.tenantId()).param("d",id).param("s",next.name()).param("u",p.userId()).param("n",notes).param("o",old==null?null:old.name()).param("c",UUID.randomUUID().toString()).update();}private void syncOrder(IdentityPrincipal p,UUID order,Status s){String x=s==Status.ASSIGNED?"ASSIGNED":s==Status.PICKED_UP?"PICKED_UP":s==Status.IN_TRANSIT?"ON_THE_WAY":s==Status.DELIVERED?"DELIVERED":s==Status.CANCELLED?"CANCELLED":null;if(x!=null){db.sql("update orders set status=:s,updated_at=now() where id=:o and tenant_id=:t").param("s",x).param("o",order).param("t",p.tenantId()).update();db.sql("insert into order_status_history(id,tenant_id,order_id,status,changed_by) values(gen_random_uuid(),:t,:o,:s,:u)").param("t",p.tenantId()).param("o",order).param("s",x).param("u",p.userId()).update();}}private void audit(IdentityPrincipal p,String a,UUID id){db.sql("insert into audit_logs(tenant_id,user_id,action,entity_type,entity_id) values(:t,:u,:a,'DELIVERY',:i)").param("t",p.tenantId()).param("u",p.userId()).param("a",a).param("i",id).update();}private void required(String k){if(k==null||k.isBlank())throw err(HttpStatus.BAD_REQUEST,"IDEMPOTENCY_KEY_REQUIRED","EnvÃ­a Idempotency-Key");}private ApiException err(HttpStatus s,String c,String m){return new ApiException(s,c,m);}}

